/// The status/health warning for conversations the watcher keeps deferring
/// after a bounded-guard NoMem (GH#510). They are not quarantined, but they are
/// missing from search until one ingests.
pub(crate) fn watch_nomem_deferral_warning(deferred_conversations: u64) -> String {
    format!(
        "{deferred_conversations} conversation(s) are deferred by the watcher after repeated bounded-allocation NoMem and are missing from search until they ingest; `cass quarantine list --json` lists them"
    )
}

pub(crate) fn run_status(
    data_dir_override: &Option<PathBuf>,
    db_override: Option<PathBuf>,
    output_format: Option<RobotFormat>,
    stale_threshold: u64,
    _robot_meta: bool,
) -> CliResult<()> {
    // k2k20 ask #1: status opens the canonical DB and was observed silent
    // for 13+ minutes on a 9.3GB corpus; share the doctor liveness heartbeat
    // (stderr only, first tick after one full interval).
    let _heartbeat = CliHeartbeat::start("status");
    let data_dir = resolve_data_dir(data_dir_override, db_override.as_ref());
    let db_path = db_override.unwrap_or_else(|| data_dir.join("agent_search.db"));
    // Bounded execution budget for the robot surface (uojcg.2.2): when the
    // optional/expensive sections would exceed it, status sheds them and returns
    // a parseable partial result (with timed_out + skipped_sections) instead of
    // blocking on a slow filesystem/coverage scan.
    let status_budget = crate::robot_budget_envelope::RobotBudget::new(status_budget_ms());
    let mut state = state_meta_json_for_status(&data_dir, &db_path, stale_threshold);
    refresh_state_database_counts_if_needed(&mut state, &db_path, "status");
    maybe_test_status_delay();

    let index_exists = state
        .get("index")
        .and_then(|i| i.get("exists"))
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    // b4uax: legacy Tantivy generation — exists, but unreadable by the
    // current engine; the only fix is a full rebuild, not a refresh.
    let index_engine_incompatible = state
        .get("index")
        .and_then(|i| i.get("engine_incompatible"))
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let index_fresh = state
        .get("index")
        .and_then(|i| i.get("fresh"))
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    // GH #457: served count contradicts the completed checkpoint.
    let index_hollow = state
        .get("index")
        .and_then(|i| i.get("hollow"))
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let index_age_secs = state
        .get("index")
        .and_then(|i| i.get("age_seconds"))
        .cloned()
        .unwrap_or(serde_json::Value::Null);
    let is_stale = state
        .get("index")
        .and_then(|i| i.get("stale"))
        .and_then(|v| v.as_bool())
        .unwrap_or(true);
    let rebuild_active = state
        .get("rebuild")
        .and_then(|r| r.get("active"))
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let rebuild_stalled = state
        .get("rebuild")
        .and_then(|r| r.get("stalled"))
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let rebuild_processed = state
        .get("rebuild")
        .and_then(|r| r.get("processed_conversations"))
        .and_then(|v| v.as_u64());
    let rebuild_total = state
        .get("rebuild")
        .and_then(|r| r.get("total_conversations"))
        .and_then(|v| v.as_u64());
    let db_exists = state
        .get("database")
        .and_then(|d| d.get("exists"))
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let db_opened = state
        .get("database")
        .and_then(|d| d.get("opened"))
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let db_open_error = state
        .get("database")
        .and_then(|d| d.get("open_error"))
        .and_then(|v| v.as_str())
        .map(str::to_string);
    let db_open_retryable = state
        .get("database")
        .and_then(|d| d.get("open_retryable"))
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let counts_skipped = state
        .get("database")
        .and_then(|d| d.get("counts_skipped"))
        .and_then(|v| v.as_bool())
        .unwrap_or(true);
    let open_skipped = state
        .get("database")
        .and_then(|d| d.get("open_skipped"))
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let pending_sessions = state
        .get("pending")
        .and_then(|p| p.get("sessions"))
        .and_then(|v| v.as_u64())
        .unwrap_or(0);
    let semantic_summary = state
        .get("semantic")
        .and_then(|s| s.get("summary"))
        .and_then(|v| v.as_str())
        .unwrap_or("Semantic asset status unknown");
    let semantic_status = state
        .get("semantic")
        .and_then(|s| s.get("status"))
        .and_then(|v| v.as_str())
        .unwrap_or("unknown");
    let semantic_hint = state
        .get("semantic")
        .and_then(|s| s.get("hint"))
        .and_then(|v| v.as_str());
    let index_empty_with_messages = state
        .get("index")
        .and_then(|i| i.get("empty_with_messages"))
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let quarantined_conversations = state
        .get("ingest_quarantine")
        .and_then(|q| q.get("quarantined_conversations"))
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(0);
    let recent_quarantined_conversations = state
        .get("ingest_quarantine")
        .and_then(|q| q.get("recent_quarantined_conversations"))
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(0);
    let ingest_quarantine_critical = state
        .get("ingest_quarantine")
        .and_then(|q| q.get("circuit_breaker_active"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let ingest_quarantine_recommended_action = state
        .get("ingest_quarantine")
        .and_then(|q| q.get("recommended_action"))
        .and_then(serde_json::Value::as_str)
        .map(str::to_string);
    // i6upe: live bounded real-column probe verdict (milliseconds), the fast
    // complement to the persisted #331 deep-probe attestation below.
    let db_integrity = state
        .get("database")
        .and_then(|d| d.get("integrity"))
        .and_then(|v| v.as_str())
        .unwrap_or("unknown")
        .to_string();
    let db_integrity_hint = state
        .get("database")
        .and_then(|d| d.get("integrity_hint"))
        .and_then(|v| v.as_str())
        .map(str::to_string);
    let live_integrity_corrupt = db_integrity == "corrupt";
    let mut warnings = Vec::<String>::new();
    if live_integrity_corrupt {
        warnings.push(db_integrity_hint.clone().unwrap_or_else(|| {
            "the canonical archive's stored pages are malformed (bounded real-column probe); do NOT run 'cass index' — run 'cass doctor --check' and recover first".to_string()
        }));
    }
    if ingest_quarantine_critical {
        warnings.push(format!(
            "{recent_quarantined_conversations} recent conversation quarantine(s) triggered the ingest quarantine circuit breaker; search coverage is suspect until the watcher/source path is inspected"
        ));
    } else if quarantined_conversations > 0 {
        warnings.push(format!(
            "{quarantined_conversations} conversation(s) are excluded from search after ingest quarantine; search remains usable for the rest of the archive, and `cass quarantine list --json` names them and says whether a retry can help"
        ));
    }
    let deferred_conversations = state
        .get("ingest_quarantine")
        .and_then(|q| q.get("deferred_conversations"))
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(0);
    if deferred_conversations > 0 {
        warnings.push(watch_nomem_deferral_warning(deferred_conversations));
    }

    let db_available = db_opened || (db_exists && db_open_retryable);
    let lexical_index_initialized = cass_lexical_index_initialized(&data_dir);
    let not_initialized =
        cass_not_initialized(db_exists, lexical_index_initialized, rebuild_active);
    // #331: a fingerprint-still-valid deep-probe attestation that proved
    // committed structural corruption must gate top-level `healthy` — a
    // known-bad canonical store cannot read as healthy just because it still
    // opens and the derived lexical index remains complete.
    let attested_integrity_failure = db_exists
        && crate::search::storage_integrity::load_matching_integrity_attestation(
            &data_dir, &db_path,
        )
        .is_some_and(|attestation| {
            attestation.verdict
                == crate::search::storage_integrity::IntegrityAttestationVerdict::Fail
        });
    if attested_integrity_failure {
        warnings.push(
            "a recent integrity probe proved committed structural corruption in the canonical archive (see storage_integrity); run 'cass doctor check --json' and plan a recovery before trusting new writes"
                .to_string(),
        );
    }
    let healthy = db_exists
        && db_available
        && index_exists
        && index_fresh
        && !rebuild_active
        && !index_empty_with_messages
        && !ingest_quarantine_critical
        && !attested_integrity_failure
        && !live_integrity_corrupt;
    // Stalled rebuilds are reported as a distinct status so operators
    // can tell a wedged indexer apart from a slow-but-progressing one
    // (issue #258). `stalled` implies `rebuild_active=true`, but it
    // *overrides* the "rebuilding" status because health is not
    // monotonically improving — the operator must intervene.
    let status = if rebuild_stalled {
        "stalled"
    } else if rebuild_active {
        "rebuilding"
    } else if ingest_quarantine_critical || live_integrity_corrupt {
        "unhealthy"
    } else if healthy {
        "healthy"
    } else if not_initialized {
        "not_initialized"
    } else if db_exists && !db_available {
        "degraded"
    } else {
        "unhealthy"
    };
    let explanation = if not_initialized {
        Some(cass_not_initialized_explanation(&data_dir))
    } else {
        None
    };

    let recommended_action = if rebuild_stalled {
        Some("Index rebuild is wedged; see `cass status --json | jq .rebuild` for the stall age and capture a stack trace with `sudo gdb -batch -ex 'thread apply all bt' -p $(pgrep -f 'cass index') 2>/dev/null | head -200` for a bug report".to_string())
    } else if rebuild_active {
        Some("Index rebuild is already in progress".to_string())
    } else if live_integrity_corrupt {
        // i6upe: staleness advice ('run cass index') is the WORST action on a
        // malformed archive — recovery must come first.
        Some("The canonical archive is malformed; do NOT run 'cass index'. Run 'cass doctor check --json', then recover the database (sqlite3 agent_search.db '.recover') before reindexing".to_string())
    } else if not_initialized {
        Some(cass_not_initialized_recommended_action())
    } else if !db_exists {
        Some("Run 'cass index --full' to create the database".to_string())
    } else if !db_available {
        Some("Run 'cass doctor check --json' before any repair; indexing will not replace an unreadable canonical database".to_string())
    } else if !index_exists {
        Some("Run 'cass index --full' to rebuild the search index".to_string())
    } else if index_engine_incompatible {
        Some(
            "Run 'cass index --full' to rebuild the search index for the current engine (a legacy Tantivy generation was found; one-time full lexical rebuild, cost scales with message count — `--force-rebuild` skips the filesystem rescan)"
                .to_string(),
        )
    } else if index_hollow {
        // GH #457: name the repair (the pre-scan sparse check rebuilds the
        // generation from the canonical DB) rather than the generic stale
        // advice, so the operator knows why the next run rebuilds.
        Some(HOLLOW_INDEX_RECOMMENDED_ACTION.to_string())
    } else if state_index_manifest_corrupt(&state) {
        Some(CORRUPT_MANIFEST_RECOMMENDED_ACTION.to_string())
    } else if index_empty_with_messages {
        Some("Run 'cass index --full' to populate the empty search index".to_string())
    } else if ingest_quarantine_critical {
        ingest_quarantine_recommended_action
    } else if is_stale || pending_sessions > 0 {
        let pending_msg = if pending_sessions > 0 {
            format!(" ({pending_sessions} sessions pending)")
        } else {
            String::new()
        };
        Some(format!(
            "Run 'cass index' to refresh the index{pending_msg}"
        ))
    } else if quarantined_conversations > 0 || deferred_conversations > 0 {
        ingest_quarantine_recommended_action
    } else {
        semantic_recommended_action(&state, not_initialized)
    };

    let structured_format = output_format.or_else(robot_format_from_env).map(|fmt| {
        if matches!(fmt, RobotFormat::Sessions) {
            RobotFormat::Compact
        } else {
            fmt
        }
    });

    if let Some(fmt) = structured_format {
        let policy_registry = state
            .get("policy_registry")
            .cloned()
            .unwrap_or(serde_json::Value::Null);
        let topology_budget =
            serde_json::to_value(crate::topology_budget::inspect_host_topology_budget())
                .unwrap_or(serde_json::Value::Null);
        let daemon_runtime = probe_daemon_runtime_for_diagnostics(&data_dir);

        // Status is a readiness surface, not a doctor run. Deep coverage checks
        // verify raw-mirror manifests and can hash very large archived blobs, and
        // the quarantine scan walks the filesystem; doing that here made
        // `cass status --json` CPU-bound on real archives. These optional sections
        // are now shed when the bounded budget is tripped (uojcg.2.2), so status
        // returns a parseable PARTIAL result with timed_out + skipped_sections
        // rather than blocking. The core readiness above is cheap and always
        // present; operators are routed to `cass doctor check` for the rest.
        let mut skipped_sections: Vec<String> = Vec::new();
        let (quarantine_value, coverage_value, doctor_summary_value) = if status_budget.is_healthy()
        {
            let quarantine_report = collect_diag_quarantine_report(
                &data_dir,
                &crate::search::tantivy::expected_index_dir(&data_dir),
            );
            let coverage_risk = doctor_fast_coverage_risk_unchecked(db_exists);
            let doctor_summary = build_doctor_runtime_summary(DoctorRuntimeSummaryInput {
                surface: "status-summary",
                state: &state,
                status,
                healthy,
                initialized: !not_initialized,
                db_exists,
                rebuild_active,
                coverage_risk: &coverage_risk,
                coverage_source: "status-fast-state",
                coverage_checked: false,
                quarantine_summary: Some(&quarantine_report.summary),
                recommended_action: recommended_action.as_ref(),
                data_dir: &data_dir,
            });
            (
                serde_json::to_value(&quarantine_report).unwrap_or(serde_json::Value::Null),
                serde_json::to_value(&coverage_risk).unwrap_or(serde_json::Value::Null),
                serde_json::to_value(&doctor_summary).unwrap_or(serde_json::Value::Null),
            )
        } else {
            for section in ["quarantine", "coverage_risk", "doctor_summary"] {
                skipped_sections.push(section.to_string());
            }
            (
                serde_json::Value::Null,
                serde_json::Value::Null,
                serde_json::Value::Null,
            )
        };
        let recommended_commands = readiness_recommended_commands(
            &data_dir,
            &db_path,
            &state,
            status,
            healthy,
            not_initialized,
            recommended_action.as_deref(),
        );
        let budget_timed_out = status_budget.is_exhausted();
        let recommended_next_probe = if skipped_sections.is_empty() {
            serde_json::Value::Null
        } else {
            serde_json::Value::String("cass doctor check --json".to_string())
        };
        let payload = serde_json::json!({
            "status": status,
            "healthy": healthy,
            "health_level": if ingest_quarantine_critical { "critical" } else if healthy && quarantined_conversations > 0 { "degraded" } else { status },
            "initialized": !not_initialized,
            "explanation": explanation,
            "warnings": warnings,
            "data_dir": data_dir.display().to_string(),
            "index": state.get("index").cloned().unwrap_or(serde_json::Value::Null),
            "database": serde_json::json!({
                "exists": db_exists,
                "opened": db_opened,
                "conversations": state.get("database").and_then(|d| d.get("conversations")).cloned().unwrap_or(serde_json::Value::Null),
                "messages": state.get("database").and_then(|d| d.get("messages")).cloned().unwrap_or(serde_json::Value::Null),
                "path": db_path.display().to_string(),
                // WS-B.4a: physical footprint from metadata (see state meta).
                "db_bytes": state.get("database").and_then(|d| d.get("db_bytes")).cloned().unwrap_or(serde_json::json!(0)),
                "wal_bytes": state.get("database").and_then(|d| d.get("wal_bytes")).cloned().unwrap_or(serde_json::json!(0)),
                "shm_present": state.get("database").and_then(|d| d.get("shm_present")).cloned().unwrap_or(serde_json::json!(false)),
                "open_error": db_open_error,
                "open_retryable": db_open_retryable,
                "counts_skipped": counts_skipped,
                "open_skipped": open_skipped,
                // i6upe: live bounded real-column probe verdict — the fast,
                // distinct corruption signal (never conflated with `stale`).
                "integrity": db_integrity,
                "integrity_detail": state.get("database").and_then(|d| d.get("integrity_detail")).cloned().unwrap_or(serde_json::Value::Null),
                "integrity_hint": db_integrity_hint,
            }),
            "pending": state.get("pending").cloned().unwrap_or(serde_json::Value::Null),
            "rebuild": state.get("rebuild").cloned().unwrap_or(serde_json::Value::Null),
            "rebuild_progress": rebuild_progress_summary_json(&state),
            "semantic": state.get("semantic").cloned().unwrap_or(serde_json::Value::Null),
            "ingest_quarantine": state.get("ingest_quarantine").cloned().unwrap_or(serde_json::Value::Null),
            "policy_registry": policy_registry,
            "topology_budget": topology_budget,
            "daemon_runtime": daemon_runtime,
            "doctor_summary": doctor_summary_value,
            "coverage_risk": coverage_value,
            "quarantine": quarantine_value,
            // uojcg.3.3: compact "is search missing known conversations?" verdict,
            // derived from the cheap ingest-quarantine counts above so health and
            // status agree. `quarantine` (above) is the deep, budget-shed scan.
            "search_completeness": serde_json::to_value(
                crate::search::quarantine_status::project_search_completeness(
                    quarantined_conversations,
                    ingest_quarantine_critical,
                ),
            )
            .unwrap_or(serde_json::Value::Null),
            // uojcg.9.2/9.5: likely root-cause family attributed from the live
            // state signals (storage open failure, derived truth-table mismatch,
            // semantic load failure). Conservative — Unknown when no signal
            // implicates a family. Status is probe-free, so no host-disk signal.
            "root_cause": serde_json::to_value(
                crate::root_cause_projection::project_root_cause(
                    &gather_projection_signals_from_state(&state, None, None),
                ),
            )
            .unwrap_or(serde_json::Value::Null),
            // qfswx: project the `.14.1` storage-integrity vocabulary doctor
            // emits onto status too, so every truth surface agrees. Probe-free:
            // derives ok / openread_failed / derived_only_drift /
            // unknown_deferred from the db-open + index-drift signals above.
            "storage_integrity": storage_integrity_value_from_state(&data_dir, &db_path, &state, not_initialized),
            "recommended_action": recommended_action,
            "recommended_commands": recommended_commands,
            "budget": serde_json::json!({
                "elapsed_ms": status_budget.elapsed_ms(),
                "budget_ms": status_budget.total_ms(),
                "timed_out": budget_timed_out,
                "skipped_sections": skipped_sections,
                "recommended_next_probe": recommended_next_probe,
            }),
            "_meta": state.get("_meta").cloned().unwrap_or(serde_json::Value::Null),
        });
        return output_structured_value(payload, fmt);
    }

    let status_icon = if healthy {
        "✓"
    } else if rebuild_active {
        "~"
    } else if not_initialized {
        "○"
    } else {
        "!"
    };
    let status_word = if rebuild_active {
        "Rebuilding"
    } else if healthy {
        "Healthy"
    } else if not_initialized {
        "Not initialized yet"
    } else {
        "Attention needed"
    };

    println!("{status_icon} CASS Status: {status_word}");
    println!();

    println!("Index:");
    if index_exists {
        if let Some(age) = index_age_secs.as_u64() {
            let age_str = if age < 60 {
                format!("{age} seconds ago")
            } else if age < 3600 {
                format!("{} minutes ago", age / 60)
            } else if age < 86400 {
                format!("{} hours ago", age / 3600)
            } else {
                format!("{} days ago", age / 86400)
            };
            let stale_indicator = if is_stale { " (stale)" } else { "" };
            println!("  Last indexed: {age_str}{stale_indicator}");
        } else {
            println!("  Last indexed: unknown");
        }
        if rebuild_active {
            match (rebuild_processed, rebuild_total) {
                (Some(processed), Some(total)) => {
                    println!("  Rebuild progress: {processed}/{total} conversations committed");
                }
                _ => println!("  Rebuild progress: in progress"),
            }
        }
        if let Some(scan) = state
            .get("rebuild")
            .and_then(|rebuild| rebuild.get("expected_docs_scan"))
            .filter(|scan| !scan.is_null())
        {
            println!(
                "  Coverage scan: counted through conversation id {} of {} ({} docs so far); the next index run resumes it if the archive only grew",
                scan["last_conversation_id"],
                scan["max_conversation_id"],
                scan["expected_docs_so_far"]
            );
        }
        if index_empty_with_messages {
            println!("  Warning: index has 0 documents but database has messages");
            println!("  Run 'cass index --full' to populate the search index");
        }
    } else if not_initialized {
        println!("  Not created yet - run 'cass index --full' once");
    } else {
        println!("  Not found - run 'cass index --full'");
    }

    println!();
    println!("Database:");
    if live_integrity_corrupt {
        println!("  Integrity: MALFORMED (bounded real-column probe)");
        if let Some(detail) = state
            .get("database")
            .and_then(|d| d.get("integrity_detail"))
            .and_then(|v| v.as_str())
        {
            println!("  Detail: {detail}");
        }
        println!(
            "  Do NOT run 'cass index' — run 'cass doctor check --json' and recover the database first"
        );
    }
    if db_exists {
        if db_opened {
            if open_skipped {
                println!("  Open skipped for fast status on large database");
            } else if counts_skipped {
                println!("  Counts skipped for fast status on large database");
            } else {
                if let Some(conversations) = state
                    .get("database")
                    .and_then(|d| d.get("conversations"))
                    .and_then(|v| v.as_i64())
                {
                    println!("  Conversations: {conversations}");
                }
                if let Some(messages) = state
                    .get("database")
                    .and_then(|d| d.get("messages"))
                    .and_then(|v| v.as_i64())
                {
                    println!("  Messages: {messages}");
                }
            }
        } else if db_open_retryable {
            println!("  Temporarily busy during probe");
            if let Some(err) = &db_open_error {
                println!("  Probe error: {err}");
            }
        } else {
            println!("  Exists, but could not be opened");
            if let Some(err) = &db_open_error {
                println!("  Error: {err}");
            }
        }
    } else if not_initialized {
        println!("  Not created yet");
    } else {
        println!("  Not found");
    }

    println!();
    println!("Semantic:");
    println!("  Status: {semantic_status}");
    println!("  Summary: {semantic_summary}");
    if let Some(hint) = semantic_hint {
        println!("  Hint: {hint}");
    }

    if pending_sessions > 0 {
        println!();
        println!("Pending: {pending_sessions} sessions awaiting indexing");
    }
    if quarantined_conversations > 0 {
        println!();
        println!(
            "Warning: {quarantined_conversations} conversation(s) quarantined after ingest OOM"
        );
    }
    if deferred_conversations > 0 {
        println!();
        println!(
            "Warning: {}",
            watch_nomem_deferral_warning(deferred_conversations)
        );
    }

    if let Some(explanation) = &explanation {
        println!();
        println!("Why: {explanation}");
    }

    if let Some(action) = &recommended_action {
        println!();
        println!("Recommended: {action}");
    }

    // Bead v6vuz: mirror the robot readiness vocabulary in the human surface so
    // the operator-facing summary never contradicts `cass status --json`.
    print_human_readiness_section(
        &state,
        crate::search::readiness_projection::SurfaceKind::Status,
    );

    Ok(())
}

/// One-shot first stop for agents: never starts repair/indexing, but returns
/// exact next commands and discovery pointers for the current dataset.
pub(crate) fn triage_budget_ms(timeout_ms: Option<u64>) -> u64 {
    timeout_ms.unwrap_or_else(|| {
        dotenvy::var("CASS_TRIAGE_BUDGET_MS")
            .ok()
            .and_then(|value| value.parse::<u64>().ok())
            .filter(|&milliseconds| milliseconds > 0)
            .unwrap_or(8_000)
    })
}

/// Deterministic slowdown for the bounded triage E2E. This is inert unless the
/// explicit test-only environment variable is present.
pub(crate) fn maybe_test_triage_delay() {
    if let Ok(raw) = dotenvy::var("CASS_TEST_TRIAGE_SLOW_MS")
        && let Ok(milliseconds) = raw.parse::<u64>()
        && milliseconds > 0
    {
        std::thread::sleep(Duration::from_millis(milliseconds));
    }
}

pub(crate) const TRIAGE_RESPONSE_RESERVE_MS: u64 = 25;

pub(crate) fn triage_remaining_operation_timeout(
    budget: &crate::robot_budget_envelope::RobotBudget,
) -> Option<Duration> {
    let milliseconds = budget
        .remaining_ms()
        .saturating_sub(TRIAGE_RESPONSE_RESERVE_MS);
    (milliseconds > 0).then(|| Duration::from_millis(milliseconds))
}

#[derive(Clone, Copy)]
pub(crate) struct TriageCoreReadiness {
    pub(crate) db_exists: bool,
    pub(crate) lexical_exists: bool,
}

pub(crate) enum TriageReadinessWorkerMessage {
    Core(TriageCoreReadiness),
    Complete(serde_json::Value),
}

pub(crate) fn triage_budget_fallback_state(
    data_dir: &Path,
    db_path: &Path,
    core: Option<TriageCoreReadiness>,
) -> serde_json::Value {
    let db_exists = core
        .map(|facts| serde_json::Value::Bool(facts.db_exists))
        .unwrap_or(serde_json::Value::Null);
    let lexical_exists = core
        .map(|facts| serde_json::Value::Bool(facts.lexical_exists))
        .unwrap_or(serde_json::Value::Null);
    serde_json::json!({
        "index": {
            "exists": lexical_exists,
            "status": "not_inspected",
            "inspected": false,
            "reason": "Detailed index readiness was skipped because the triage execution budget was exhausted."
        },
        "database": {
            "exists": db_exists,
            "inspected": false,
            "open_error": "Database readiness probe was skipped because the triage execution budget was exhausted.",
            "counts_skipped": true,
            "open_skipped": true,
        },
        "pending": { "inspected": false },
        "rebuild": { "inspected": false },
        "semantic": {
            "status": "not_inspected",
            "inspected": false,
            "summary": "Semantic readiness was skipped because the triage execution budget was exhausted.",
            "hint": "Retry the recommended bounded triage probe to recover semantic readiness.",
        },
        "ingest_quarantine": {
            "status": "not_inspected",
            "inspected": false,
        },
        "_meta": {
            "timestamp": chrono::Utc::now().to_rfc3339(),
            "data_dir": data_dir.display().to_string(),
            "db_path": db_path.display().to_string(),
        }
    })
}

pub(crate) fn triage_readiness_state_with_hard_timeout(
    data_dir: &Path,
    db_path: &Path,
    stale_threshold: u64,
    budget: &crate::robot_budget_envelope::RobotBudget,
) -> (serde_json::Value, bool) {
    let Some(timeout) = triage_remaining_operation_timeout(budget) else {
        return (triage_budget_fallback_state(data_dir, db_path, None), true);
    };

    let worker_data_dir = data_dir.to_path_buf();
    let worker_db_path = db_path.to_path_buf();
    let (tx, rx) = std::sync::mpsc::channel();
    let Ok(_state_worker) = std::thread::Builder::new()
        .name("cass-triage-readiness-probe".to_string())
        .spawn(move || {
            maybe_test_triage_worker_delay("CASS_TEST_TRIAGE_CORE_SLOW_MS");
            let core = TriageCoreReadiness {
                db_exists: worker_db_path.is_file(),
                lexical_exists: cass_lexical_index_initialized(&worker_data_dir),
            };
            if tx.send(TriageReadinessWorkerMessage::Core(core)).is_err() {
                return;
            }
            maybe_test_triage_delay();
            maybe_test_triage_worker_delay("CASS_TEST_TRIAGE_STATE_DB_SLOW_MS");
            let state =
                state_meta_json_for_status(&worker_data_dir, &worker_db_path, stale_threshold);
            let _ = tx.send(TriageReadinessWorkerMessage::Complete(state));
        })
    else {
        return (triage_budget_fallback_state(data_dir, db_path, None), true);
    };

    let wait_start = std::time::Instant::now();
    match rx.recv_timeout(timeout) {
        Ok(TriageReadinessWorkerMessage::Complete(state)) => (state, false),
        Ok(TriageReadinessWorkerMessage::Core(core)) => {
            let remaining = timeout.saturating_sub(wait_start.elapsed());
            if remaining.is_zero() {
                (
                    triage_budget_fallback_state(data_dir, db_path, Some(core)),
                    true,
                )
            } else {
                match rx.recv_timeout(remaining) {
                    Ok(TriageReadinessWorkerMessage::Complete(state)) => (state, false),
                    Ok(TriageReadinessWorkerMessage::Core(_))
                    | Err(
                        std::sync::mpsc::RecvTimeoutError::Timeout
                        | std::sync::mpsc::RecvTimeoutError::Disconnected,
                    ) => (
                        triage_budget_fallback_state(data_dir, db_path, Some(core)),
                        true,
                    ),
                }
            }
        }
        Err(
            std::sync::mpsc::RecvTimeoutError::Timeout
            | std::sync::mpsc::RecvTimeoutError::Disconnected,
        ) => (triage_budget_fallback_state(data_dir, db_path, None), true),
    }
}

pub(crate) fn triage_recovery_probe(
    data_dir: &Path,
    db_path: &Path,
    budget: &crate::robot_budget_envelope::RobotBudget,
    stale_threshold: u64,
) -> String {
    let retry_budget_ms = budget.total_ms().saturating_mul(4).max(60_000);
    cass_dataset_command(
        data_dir,
        db_path,
        &[
            "triage",
            "--json",
            "--stale-threshold",
            &stale_threshold.to_string(),
            "--timeout",
            &retry_budget_ms.to_string(),
        ],
    )
}

pub(crate) fn triage_uninspected_search_completeness(recovery_probe: &str) -> serde_json::Value {
    serde_json::json!({
        "inspected": false,
        "quarantine_status": "not_inspected",
        "quarantined_conversations": serde_json::Value::Null,
        "complete": serde_json::Value::Null,
        "can_search": serde_json::Value::Null,
        "coverage_suspect": serde_json::Value::Null,
        "impact": "Search completeness was not inspected before the triage budget expired.",
        "next_command": recovery_probe,
    })
}

pub(crate) fn triage_uninspected_root_cause(recovery_probe: &str) -> serde_json::Value {
    serde_json::json!({
        "schema_version": crate::root_cause_taxonomy::ROOT_CAUSE_TAXONOMY_VERSION,
        "inspected": false,
        "family": "unknown",
        "locus": "unknown",
        "confidence": "unknown",
        "evidence_refs": [],
        "summary": "No root cause was attributed because readiness probes did not complete.",
        "recommended_next_probe": recovery_probe,
    })
}

pub(crate) fn triage_recovery_recommended_commands(recovery_probe: &str) -> Vec<serde_json::Value> {
    vec![readiness_command_recommendation(
        ReadinessCommandRecommendation {
            id: "retry-bounded-triage",
            command: recovery_probe.to_string(),
            purpose: "Recover the readiness sections skipped by the bounded triage probe.",
            safety: "read-only",
            run_when: "Run when triage budget.skipped_sections is non-empty.",
            success_signal: "budget.skipped_sections=[]",
            parse_fields: &[
                "status",
                "readiness",
                "search_completeness",
                "root_cause",
                "budget",
            ],
            retry_after_ms: None,
        },
    )]
}

pub(crate) fn run_triage(
    data_dir_override: &Option<PathBuf>,
    db_override: Option<PathBuf>,
    output_format: Option<RobotFormat>,
    stale_threshold: u64,
    timeout_ms: Option<u64>,
) -> CliResult<()> {
    let data_dir = resolve_data_dir(data_dir_override, db_override.as_ref());
    let db_path = db_override.unwrap_or_else(|| data_dir.join("agent_search.db"));
    let triage_budget =
        crate::robot_budget_envelope::RobotBudget::new(triage_budget_ms(timeout_ms));
    let (mut state, readiness_state_skipped) = triage_readiness_state_with_hard_timeout(
        &data_dir,
        &db_path,
        stale_threshold,
        &triage_budget,
    );
    let mut hard_probe_timed_out = readiness_state_skipped;
    let mut skipped_sections = Vec::<String>::new();
    if readiness_state_skipped {
        skipped_sections.extend(
            [
                "readiness_state",
                "index_readiness",
                "database_readiness",
                "pending_readiness",
                "rebuild_readiness",
                "semantic_readiness",
                "ingest_quarantine_readiness",
            ]
            .into_iter()
            .map(str::to_string),
        );
    }
    if !readiness_state_skipped && state_database_counts_need_refresh(&state, &db_path) {
        match triage_remaining_operation_timeout(&triage_budget) {
            Some(timeout) => {
                if refresh_state_database_counts_with_hard_timeout(
                    &mut state, &db_path, "triage", timeout,
                ) == BoundedCountRefresh::TimedOut
                {
                    hard_probe_timed_out = true;
                    skipped_sections.push("database_counts".to_string());
                }
            }
            None => skipped_sections.push("database_counts".to_string()),
        }
    } else if readiness_state_skipped {
        skipped_sections.push("database_counts".to_string());
    }

    let index_exists = state
        .get("index")
        .and_then(|index| index.get("exists"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    // b4uax: legacy Tantivy generation — exists, but unreadable by the
    // current engine; the only fix is a full rebuild, not a refresh.
    let index_engine_incompatible = state
        .get("index")
        .and_then(|index| index.get("engine_incompatible"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let index_fresh = state
        .get("index")
        .and_then(|index| index.get("fresh"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let is_stale = state
        .get("index")
        .and_then(|index| index.get("stale"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(true);
    let rebuild_active = state
        .get("rebuild")
        .and_then(|rebuild| rebuild.get("active"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let rebuild_stalled = state
        .get("rebuild")
        .and_then(|rebuild| rebuild.get("stalled"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let db_exists = state
        .get("database")
        .and_then(|database| database.get("exists"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let db_opened = state
        .get("database")
        .and_then(|database| database.get("opened"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let db_open_retryable = state
        .get("database")
        .and_then(|database| database.get("open_retryable"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let pending_sessions = state
        .get("pending")
        .and_then(|pending| pending.get("sessions"))
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(0);
    let index_empty_with_messages = state
        .get("index")
        .and_then(|index| index.get("empty_with_messages"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    // uojcg.3.3: triage previously omitted quarantine entirely; surface the same
    // cheap counts status/health use so its readiness block and search-completeness
    // verdict agree with the other surfaces.
    let quarantined_conversations = state
        .get("ingest_quarantine")
        .and_then(|q| q.get("quarantined_conversations"))
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(0);
    let ingest_quarantine_critical = state
        .get("ingest_quarantine")
        .and_then(|q| q.get("circuit_breaker_active"))
        .and_then(serde_json::Value::as_bool)
        .unwrap_or(false);
    let recovery_probe =
        triage_recovery_probe(&data_dir, &db_path, &triage_budget, stale_threshold);
    let search_completeness = if readiness_state_skipped {
        triage_uninspected_search_completeness(&recovery_probe)
    } else {
        let mut completeness = serde_json::to_value(
            crate::search::quarantine_status::project_search_completeness(
                quarantined_conversations,
                ingest_quarantine_critical,
            ),
        )
        .unwrap_or(serde_json::Value::Null);
        if let Some(object) = completeness.as_object_mut() {
            object.insert("inspected".to_string(), serde_json::Value::Bool(true));
        }
        completeness
    };
    let db_available = db_opened || (db_exists && db_open_retryable);
    // Reuse the bounded readiness snapshot. A fresh filesystem probe here
    // would escape triage's hard deadline on a degraded or remote mount.
    let lexical_index_initialized = index_exists;
    let not_initialized =
        cass_not_initialized(db_exists, lexical_index_initialized, rebuild_active);
    let observed_healthy = db_exists
        && db_available
        && index_exists
        && index_fresh
        && !rebuild_active
        && !index_empty_with_messages;
    let observed_status = if rebuild_stalled {
        "stalled"
    } else if rebuild_active {
        "rebuilding"
    } else if observed_healthy {
        "healthy"
    } else if not_initialized {
        "not_initialized"
    } else if db_exists && !db_available {
        "degraded"
    } else {
        "unhealthy"
    };
    let observed_explanation = if not_initialized {
        Some(cass_not_initialized_explanation(&data_dir))
    } else {
        None
    };
    let observed_recommended_action = if rebuild_stalled {
        Some(
            "Index rebuild is wedged; capture diagnostics for a bug report and restart the watcher"
                .to_string(),
        )
    } else if rebuild_active {
        Some("Index rebuild is already in progress".to_string())
    } else if not_initialized {
        Some(cass_not_initialized_recommended_action())
    } else if !db_exists {
        Some("Run 'cass index --full' to create the database".to_string())
    } else if !db_available {
        Some("Run 'cass doctor check --json' before any repair; indexing will not replace an unreadable canonical database".to_string())
    } else if !index_exists {
        Some("Run 'cass index --full' to rebuild the search index".to_string())
    } else if index_engine_incompatible {
        Some(
            "Run 'cass index --full' to rebuild the search index for the current engine (a legacy Tantivy generation was found; one-time full lexical rebuild, cost scales with message count — `--force-rebuild` skips the filesystem rescan)"
                .to_string(),
        )
    } else if index_empty_with_messages {
        Some("Run 'cass index --full' to populate the empty search index".to_string())
    } else if is_stale || pending_sessions > 0 {
        let pending_msg = if pending_sessions > 0 {
            format!(" ({pending_sessions} sessions pending)")
        } else {
            String::new()
        };
        Some(format!(
            "Run 'cass index' to refresh the index{pending_msg}"
        ))
    } else {
        semantic_recommended_action(&state, not_initialized)
    };
    let observed_recommended_commands = readiness_recommended_commands(
        &data_dir,
        &db_path,
        &state,
        observed_status,
        observed_healthy,
        not_initialized,
        observed_recommended_action.as_deref(),
    );
    let observed_next_command = observed_recommended_commands
        .first()
        .and_then(|command| command.get("command"))
        .and_then(serde_json::Value::as_str)
        .map(str::to_string);
    let mut observed_root_cause =
        serde_json::to_value(crate::root_cause_projection::project_root_cause(
            &gather_projection_signals_from_state(&state, None, None),
        ))
        .unwrap_or(serde_json::Value::Null);
    if let Some(object) = observed_root_cause.as_object_mut() {
        object.insert("inspected".to_string(), serde_json::Value::Bool(true));
    }
    let (
        status,
        healthy,
        initialized,
        explanation,
        recommended_action,
        recommended_commands,
        next_command,
        root_cause,
        rebuild_progress,
    ) = if readiness_state_skipped {
        (
            "partial",
            false,
            db_exists || lexical_index_initialized,
            Some(
                "Readiness probes did not complete within the triage execution budget.".to_string(),
            ),
            Some(recovery_probe.clone()),
            triage_recovery_recommended_commands(&recovery_probe),
            Some(recovery_probe.clone()),
            triage_uninspected_root_cause(&recovery_probe),
            serde_json::json!({ "inspected": false }),
        )
    } else {
        (
            observed_status,
            observed_healthy,
            !not_initialized,
            observed_explanation,
            observed_recommended_action,
            observed_recommended_commands,
            observed_next_command,
            observed_root_cause,
            rebuild_progress_summary_json(&state),
        )
    };

    let starter_workflows = if triage_budget.is_healthy() {
        build_workflow_capabilities()
    } else {
        skipped_sections.push("starter_workflows".to_string());
        Vec::new()
    };
    let mistake_recoveries = if triage_budget.is_healthy() {
        build_mistake_recovery_capabilities()
    } else {
        skipped_sections.push("mistake_recoveries".to_string());
        Vec::new()
    };
    let recommended_next_probe = if skipped_sections.is_empty() {
        None
    } else {
        Some(recovery_probe)
    };
    let mut budget = crate::robot_budget_envelope::BudgetBlock::from_budget(
        &triage_budget,
        skipped_sections,
        recommended_next_probe,
    );
    if hard_probe_timed_out {
        // The readiness/count worker reached its hard sub-deadline. Reserve
        // time is intentionally kept for emitting valid JSON, so wall-clock
        // sampling may be just below the outer cap; make the timeout explicit
        // and keep the budget snapshot internally consistent.
        budget.elapsed_ms = budget.elapsed_ms.max(budget.budget_ms);
        budget.timed_out = true;
    }

    let payload = serde_json::json!({
        "surface": "triage",
        "schema_version": 1,
        "status": status,
        "healthy": healthy,
        "initialized": initialized,
        "explanation": explanation,
        "recommended_action": recommended_action,
        "recommended_commands": recommended_commands,
        "next_command": next_command,
        "search_completeness": search_completeness,
        // uojcg.9.2/9.5: same conservative root-cause attribution as status
        // when inspected; an exhausted readiness probe is explicitly unknown.
        "root_cause": root_cause,
        "readiness": {
            "index": state.get("index").cloned().unwrap_or(serde_json::Value::Null),
            "database": state.get("database").cloned().unwrap_or(serde_json::Value::Null),
            "pending": state.get("pending").cloned().unwrap_or(serde_json::Value::Null),
            "rebuild": state.get("rebuild").cloned().unwrap_or(serde_json::Value::Null),
            "rebuild_progress": rebuild_progress,
            "semantic": state.get("semantic").cloned().unwrap_or(serde_json::Value::Null),
            "ingest_quarantine": state.get("ingest_quarantine").cloned().unwrap_or(serde_json::Value::Null),
        },
        "discovery": {
            "capabilities_command": "cass capabilities --json",
            "schemas_command": "cass introspect --json",
            "docs_command": "cass robot-docs guide",
            "api_version_command": "cass api-version --json",
        },
        "starter_workflows": starter_workflows,
        "mistake_recoveries": mistake_recoveries,
        "budget": budget,
        "_meta": state.get("_meta").cloned().unwrap_or(serde_json::Value::Null),
    });

    let structured_format = output_format.or_else(robot_format_from_env).map(|fmt| {
        if matches!(fmt, RobotFormat::Sessions) {
            RobotFormat::Compact
        } else {
            fmt
        }
    });

    if let Some(fmt) = structured_format {
        return output_structured_value(payload, fmt);
    }

    println!("CASS agent triage: {status}");
    if let Some(action) = payload
        .get("recommended_action")
        .and_then(serde_json::Value::as_str)
    {
        println!("Recommended: {action}");
    }
    if let Some(command) = payload
        .get("next_command")
        .and_then(serde_json::Value::as_str)
    {
        println!("Next command: {command}");
    }
    if payload
        .pointer("/budget/skipped_sections")
        .and_then(serde_json::Value::as_array)
        .is_some_and(|sections| !sections.is_empty())
    {
        println!("Budget-limited result: optional triage sections were skipped");
        if let Some(probe) = payload
            .pointer("/budget/recommended_next_probe")
            .and_then(serde_json::Value::as_str)
        {
            println!("Recovery probe: {probe}");
        }
    }
    println!("Machine output: cass triage --json");

    // Bead v6vuz: same bounded readiness summary as `status`, in triage's
    // agent-oriented vocabulary, so the human and `--json` triage agree.
    if !readiness_state_skipped {
        print_human_readiness_section(
            &state,
            crate::search::readiness_projection::SurfaceKind::Triage,
        );
    }

    Ok(())
}

/// Assemble and emit the redacted recovery/support evidence bundle (bead
/// `coding_agent_session_search-6f1lm`; the `.13.3` contract). Composes the
/// canonical readiness, next-command, source-doctor, quarantine, and
/// root-cause contracts — verbatim — into one share-safe
/// bundle via [`crate::recovery_support_bundle::build_support_bundle`], so the
/// bundle can never contradict the matching robot JSON.
///
/// Redaction is share-safe by default (raw payloads suppressed, content
/// fingerprints hashed, filesystem paths truncated to basenames). `--include-
/// full-paths` and `--include-raw-evidence` flip the [`RedactionPolicy`] and are
/// recorded in the bundle's `opt_in_flags`. `ExecutionMode::Live` marks the
/// provenance as a real on-host run (vs. the deterministic fixture mode the
/// goldens use).
pub(crate) fn run_support_bundle(
    data_dir_override: &Option<PathBuf>,
    db_override: Option<PathBuf>,
    output_format: Option<RobotFormat>,
    stale_threshold: u64,
    include_full_paths: bool,
    include_raw_evidence: bool,
) -> CliResult<()> {
    use crate::recovery_support_bundle as rsb;

    let data_dir = resolve_data_dir(data_dir_override, db_override.as_ref());
    let db_path = db_override.unwrap_or_else(|| data_dir.join("agent_search.db"));
    let data_dir_str = data_dir.display().to_string();

    // One live state snapshot (status-like: derive from the real DB-open
    // signal), reused for both the truth table and the root-cause signals so the
    // bundle is internally consistent and probes the data dir only once.
    let state = state_meta_json(&data_dir, &db_path, stale_threshold, true);
    let table = build_truth_table_from_state(&state);

    // Composed canonical contracts (verbatim from the same projections the robot
    // surfaces serialize).
    let readiness = crate::search::readiness_projection::project(
        &table,
        crate::search::readiness_projection::SurfaceKind::Triage,
    );
    let command_envelope = table.next_command_envelope(Some(&data_dir_str));
    let quarantine = table.quarantine.clone();
    let root_cause = crate::root_cause_projection::project_root_cause(
        &gather_projection_signals_from_state(&state, None, None),
    );

    // Local source provenance: a single read-only "local" observation derived
    // from the live truth table — this surface performs no remote probe, so it
    // only records local facts the bundle gathered.
    let source_provenance = rsb::SourceProvenance {
        source_id: "local".to_string(),
        cass_present: true,
        cass_current: true,
        archive_db_present: db_path.exists(),
        lexical_metadata_present: table.lexical_metadata.present,
    };

    let generated_at_ms = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| (d.as_millis().min(i64::MAX as u128)) as i64)
        .unwrap_or(0);

    // Share-safe default; the opt-in flags relax it and are recorded in the
    // bundle's redaction report.
    let mut policy = rsb::default_redaction_policy();
    if include_full_paths {
        policy.allow_full_paths = true;
    }
    if include_raw_evidence {
        policy.private_text = crate::search::incident_redaction::PrivateTextPolicy::RawOptIn;
    }

    let inputs = rsb::SupportBundleInputs {
        bundle_id: format!("support-bundle-{generated_at_ms}"),
        cass_version: env!("CARGO_PKG_VERSION").to_string(),
        // Single local host/source: identity fields are multi-source
        // concepts and are omitted (not guessed) for the local surface.
        host_id: None,
        source_id: None,
        data_dir: Some(data_dir_str),
        config_dir: None,
        model_dir: None,
        command_provenance: "cass support-bundle".to_string(),
        generated_at_ms,
        fixture_id: None,
        readiness,
        command_envelope,
        source_provenance,
        quarantine,
        root_cause,
        proof_logs: Vec::new(),
    };

    let bundle = rsb::build_support_bundle(inputs, policy, rsb::ExecutionMode::Live);

    let structured_format = output_format.or_else(robot_format_from_env).map(|fmt| {
        if matches!(fmt, RobotFormat::Sessions) {
            RobotFormat::Compact
        } else {
            fmt
        }
    });

    if let Some(fmt) = structured_format {
        let payload = serde_json::to_value(&bundle).unwrap_or(serde_json::Value::Null);
        return output_structured_value(payload, fmt);
    }

    // Bounded, share-safety-first human summary. Reuses the v6vuz human
    // readiness projection for the readiness line so it matches the other
    // surfaces verbatim.
    let human = crate::search::human_readiness_summary::project_human_summary(
        &table,
        crate::search::readiness_projection::SurfaceKind::Status,
    );
    println!("CASS support bundle");
    println!();
    println!("  Bundle ID: {}", bundle.manifest.bundle_id);
    println!("  cass version: {}", bundle.manifest.cass_version);
    println!("  Mode: live");
    println!(
        "  Share-safe: {}",
        if bundle.is_share_safe() {
            "yes"
        } else {
            "no (opt-in evidence included)"
        }
    );
    println!(
        "  Manifest complete: {}",
        if bundle.manifest.is_complete() {
            "yes"
        } else {
            "no"
        }
    );
    println!();
    println!("{}", human.headline);
    println!("  Safest next step: {}", human.safest_next_action);
    println!();
    println!("Redaction posture:");
    if !bundle.redaction.fields_suppressed.is_empty() {
        println!(
            "  Suppressed: {}",
            bundle.redaction.fields_suppressed.join(", ")
        );
    }
    if !bundle.redaction.fields_truncated.is_empty() {
        println!(
            "  Truncated to basename: {}",
            bundle.redaction.fields_truncated.join(", ")
        );
    }
    if !bundle.redaction.opt_in_flags.is_empty() {
        println!(
            "  Opt-in available: {}",
            bundle.redaction.opt_in_flags.join(", ")
        );
    }
    println!();
    println!("Machine output: cass support-bundle --json");

    Ok(())
}

/// Archive-independent executable probe for package and binary-promotion gates.
///
/// This deliberately does not resolve a data directory or database override.
/// The probe exercises the linked frankensqlite engine against an in-memory
/// database, including a write and typed read, so a stale, corrupt, locked, or
/// multi-gigabyte archive cannot affect its cost or exit status (#398).
pub(crate) fn run_selftest(output_format: Option<RobotFormat>) -> CliResult<()> {
    let start = Instant::now();
    let database_probe = (|| -> std::result::Result<i64, crate::franken_sync::FrankenError> {
        let conn = crate::franken_sync::Connection::open(":memory:")?;
        conn.execute_batch(
            "CREATE TABLE cass_selftest_probe (value INTEGER NOT NULL); \
             INSERT INTO cass_selftest_probe (value) VALUES (42);",
        )?;
        conn.query_row("SELECT value FROM cass_selftest_probe LIMIT 1;")?
            .get_typed::<i64>(0)
    })();

    let (functional, check_status, detail, probe_error) = match database_probe {
        Ok(42) => (
            true,
            "pass",
            "opened an in-memory frankensqlite database and round-tripped a typed value"
                .to_string(),
            None,
        ),
        Ok(value) => {
            let message = format!("in-memory database returned {value}, expected 42");
            (false, "fail", message.clone(), Some(message))
        }
        Err(error) => {
            let message = format!("in-memory frankensqlite probe failed: {error}");
            (false, "fail", message.clone(), Some(message))
        }
    };
    let latency_ms = start.elapsed().as_millis() as u64;

    let structured_format = output_format.or_else(robot_format_from_env).map(|format| {
        if matches!(format, RobotFormat::Sessions) {
            RobotFormat::Compact
        } else {
            format
        }
    });
    let structured_output = structured_format.is_some();
    if let Some(format) = structured_format {
        output_structured_value(
            serde_json::json!({
                "schema_version": 1,
                "status": if functional { "ok" } else { "error" },
                "functional": functional,
                "archive_accessed": false,
                "version": env!("CARGO_PKG_VERSION"),
                "contract_version": CONTRACT_VERSION,
                "latency_ms": latency_ms,
                "checks": [{
                    "name": "frankensqlite-in-memory-roundtrip",
                    "status": check_status,
                    "detail": detail,
                }],
            }),
            format,
        )?;
    } else if functional {
        println!("✓ cass executable self-test passed ({latency_ms}ms)");
        println!("  frankensqlite in-memory round-trip: pass");
        println!("  configured archive accessed: no");
    } else {
        println!("✗ cass executable self-test failed ({latency_ms}ms)");
        println!("  {detail}");
        println!("  configured archive accessed: no");
    }

    if functional {
        Ok(())
    } else {
        let error = CliError {
            code: 1,
            kind: CliErrorKind::Selftest.kind_str(),
            message: probe_error.unwrap_or_else(|| "executable self-test failed".to_string()),
            hint: Some(
                "Reinstall the cass binary from a checksum-verified release artifact.".to_string(),
            ),
            retryable: false,
        };
        if structured_output {
            Err(CliError::already_reported_from(&error))
        } else {
            Err(error)
        }
    }
}

/// GH #457: `errors[]` entry for a hollow lexical generation on `cass health`.
pub(crate) const HOLLOW_INDEX_HEALTH_ERROR: &str = "index hollow — the published lexical generation serves far fewer documents than its completed rebuild checkpoint certified; run 'cass index' to rebuild it from the canonical database";

/// GH #457: `recommended_action` shared by `cass health` and `cass status`
/// for a hollow lexical generation.
pub(crate) const HOLLOW_INDEX_RECOMMENDED_ACTION: &str = "Run 'cass index' to rebuild the hollow search index from the canonical database (the published generation serves far fewer documents than its completed checkpoint certified; the pre-scan repair rebuilds it, and 'cass index --full' does the same after a full rescan).";

/// mknmt: `errors[]` entry on `cass health` when readers serve `MANIFEST.prev`
/// because the current MANIFEST is corrupt.
pub(crate) const CORRUPT_MANIFEST_HEALTH_ERROR: &str = "index MANIFEST corrupt — search serves the previous lexical generation (MANIFEST.prev), which lacks the newest publish; run 'cass index' to rebuild it from the canonical database";

/// mknmt: `recommended_action` shared by `cass health` and `cass status` for
/// a corrupt current MANIFEST.
pub(crate) const CORRUPT_MANIFEST_RECOMMENDED_ACTION: &str = "Run 'cass index' to rebuild the search index from the canonical database (its current MANIFEST is corrupt, so search serves the previous generation from MANIFEST.prev, which lacks the newest publish; 'cass index --full' does the same after a full rescan).";

/// mknmt: readers serve `MANIFEST.prev` because the current slot is corrupt.
pub(crate) fn state_index_manifest_corrupt(state: &serde_json::Value) -> bool {
    state
        .get("index")
        .and_then(|index| index.get("manifest_source"))
        .and_then(serde_json::Value::as_str)
        == Some(
            crate::search::quill_bridge::QuillManifestSource::PreviousAfterCorruptCurrent.as_str(),
        )
}
